import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { FlatList, Modal, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import { Feather } from '@expo/vector-icons';
import { AppButton, AppInput, EmptyState, SearchInput, ScreenContainer, useSnackbar } from '@/components/ui';
import { uiText } from '@/i18n';
import { useAppStore } from '@/store/useAppStore';
import { radius, spacing, typography, useAppTheme } from '@/theme';
import { PaymentMode, Product, PurchaseReceipt, PurchaseReceiptInputItem, PurchaseReturn, PurchaseReturnInputItem, Supplier, SupplierAccountEntry, SupplierAccountSummary, SupplierInput, SupplierPayment } from '@/types';
import { formatUsdCents, parseUsdToCents } from '@/utils/multiCurrency';
import { formatNumber, formatProductUsd } from '@/utils/formatters';
import { sharePurchaseReceipt } from '@/utils/purchaseReceiptReport';
import { sharePurchaseReturn } from '@/utils/purchaseReturnReport';
import { calculateSupplierPaymentEquivalent, parseSignedUsdToCents } from '@/utils/supplierAccounts';
import { shareSupplierPayment, shareSupplierStatement } from '@/utils/supplierAccountReport';

type Section = 'inventory' | 'suppliers' | 'receipts';
type ReceiptLine = { product: Product; quantity: string; cost: string };

export function PurchasesScreen({ section, onSectionChange, bottomNavigationInset = 0 }: { section: Exclude<Section, 'inventory'>; onSectionChange: (section: Section) => void; bottomNavigationInset?: number }) {
  const store = useAppStore(); const copy = uiText(store.language); const rtl = store.language === 'ar'; const { colors } = useAppTheme();
  const compact = useWindowDimensions().width < 360;
  const [supplierEditor, setSupplierEditor] = useState<Supplier | 'new' | null>(null); const [supplierDetail, setSupplierDetail] = useState<Supplier | null>(null);
  const [receiptEditor, setReceiptEditor] = useState(false); const [receiptDetail, setReceiptDetail] = useState<PurchaseReceipt | null>(null); const [receiptSucceeded, setReceiptSucceeded] = useState(false);
  const [returnEditorReceipt, setReturnEditorReceipt] = useState<PurchaseReceipt | null>(null); const [returnDetail, setReturnDetail] = useState<PurchaseReturn | null>(null); const [returnSucceeded, setReturnSucceeded] = useState(false); const [historyMode, setHistoryMode] = useState<'receipts' | 'returns'>('receipts');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]); const [receipts, setReceipts] = useState<PurchaseReceipt[]>([]); const [returns, setReturns] = useState<PurchaseReturn[]>([]); const [search, setSearch] = useState(''); const [loading, setLoading] = useState(true);
  const [supplierSort, setSupplierSort] = useState<'name' | 'newest'>('name'); const [receiptSort, setReceiptSort] = useState<'newest' | 'oldest' | 'highest' | 'lowest'>('newest'); const [period, setPeriod] = useState<'all' | 'today' | 'week' | 'month'>('all');
  const [receiptSupplierId, setReceiptSupplierId] = useState<number | undefined>();
  const supplierFilters = useMemo<(Supplier | null)[]>(() => [null, ...suppliers], [suppliers]);
  const refresh = useCallback(async () => { setLoading(true); try { if (section === 'suppliers') setSuppliers(await store.getSuppliers(search, supplierSort, true)); else { const [receiptRows, returnRows, supplierRows] = await Promise.all([store.queryPurchaseReceipts({ search: historyMode === 'receipts' ? search : '', sort: receiptSort, period, supplierId: receiptSupplierId }), store.queryPurchaseReturns({ search: historyMode === 'returns' ? search : '', sort: receiptSort, period, supplierId: receiptSupplierId }), store.getSuppliers('', 'name', true)]); setReceipts(receiptRows); setReturns(returnRows); setSuppliers(supplierRows); } } finally { setLoading(false); } }, [historyMode, period, receiptSort, receiptSupplierId, search, section, store, supplierSort]);
  useEffect(() => { const timer = setTimeout(() => void refresh(), 180); return () => clearTimeout(timer); }, [refresh]);
  const tabs = <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}><Chip label={copy.purchase.inventoryTab} active={false} onPress={() => onSectionChange('inventory')} /><Chip label={copy.purchase.suppliersTab} active={section === 'suppliers'} onPress={() => onSectionChange('suppliers')} /><Chip label={copy.purchase.receiptsTab} active={section === 'receipts' && historyMode === 'receipts'} onPress={() => { setHistoryMode('receipts'); onSectionChange('receipts'); }} /><Chip label={copy.purchase.returnsTab} active={section === 'receipts' && historyMode === 'returns'} onPress={() => { setHistoryMode('returns'); onSectionChange('receipts'); }} /></ScrollView>;
  return <ScreenContainer><View style={styles.page}><View style={styles.header}><View style={[styles.titleRow, compact ? styles.compactTitleRow : { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={compact ? styles.compactTitleCopy : styles.flex}><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{section === 'suppliers' ? copy.purchase.suppliers : historyMode === 'returns' ? copy.purchase.returnsTab : copy.purchase.receipts}</Text><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{section === 'suppliers' ? copy.purchase.noSuppliersDescription : copy.purchase.stockOnlyNote}</Text></View>{(section === 'suppliers' || historyMode === 'receipts') && <AppButton label={section === 'suppliers' ? copy.purchase.addSupplier : copy.purchase.newReceipt} icon="plus" onPress={() => section === 'suppliers' ? setSupplierEditor('new') : setReceiptEditor(true)} style={compact ? styles.compactAction : undefined} />}</View>{tabs}<SearchInput value={search} onChangeText={setSearch} placeholder={section === 'suppliers' ? copy.purchase.supplierName : historyMode === 'returns' ? copy.purchase.returnSearch : copy.purchase.search} clearLabel={copy.common.clearSearch} rtl={rtl} />
    {section === 'suppliers' ? <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}><Chip label={copy.inventory.name} active={supplierSort === 'name'} onPress={() => setSupplierSort('name')} /><Chip label={copy.purchase.newest} active={supplierSort === 'newest'} onPress={() => setSupplierSort('newest')} /></ScrollView> : <><FlatList horizontal data={supplierFilters} keyExtractor={item => item?.uuid ?? 'all'} renderItem={({ item }) => <Chip label={item?.name ?? copy.purchase.all} active={item ? receiptSupplierId === item.id : receiptSupplierId == null} onPress={() => setReceiptSupplierId(item?.id)} />} showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips} initialNumToRender={12} maxToRenderPerBatch={12} windowSize={5} removeClippedSubviews /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['all','today','week','month'] as const).map(value => <Chip key={value} label={copy.purchase[value]} active={period === value} onPress={() => setPeriod(value)} />)}</ScrollView><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['newest','oldest','highest','lowest'] as const).map(value => <Chip key={value} label={copy.purchase[value]} active={receiptSort === value} onPress={() => setReceiptSort(value)} />)}</ScrollView></>}
    </View>
    {section === 'suppliers' ? <FlatList data={suppliers} keyExtractor={item => item.uuid} refreshing={loading} onRefresh={() => void refresh()} contentContainerStyle={[styles.list, { paddingBottom: bottomNavigationInset + spacing.md }, !suppliers.length && styles.empty]} ItemSeparatorComponent={() => <View style={styles.separator} />} renderItem={({ item }) => <Pressable accessibilityRole="button" onPress={() => setSupplierDetail(item)} style={({ pressed }) => [styles.row, { backgroundColor: colors.surface }, pressed && styles.pressed]}><View style={styles.flex}><Text numberOfLines={1} style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.name}</Text><Text numberOfLines={1} style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left', writingDirection: item.phone ? 'ltr' : undefined }]}>{item.phone || copy.purchase.receiptCount(formatNumber(item.receipt_count ?? 0, store.language))}</Text></View>{item.accounting_enabled ? <Text style={[typography.caption, { color: (item.balance_usd_cents ?? 0) > 0 ? colors.warning : colors.success, writingDirection: 'ltr' }]}>{(item.balance_usd_cents ?? 0) > 0 ? copy.purchase.payable : (item.balance_usd_cents ?? 0) < 0 ? copy.purchase.supplierCredit : copy.purchase.settled}: {formatUsdCents(Math.abs(item.balance_usd_cents ?? 0), store.language)}</Text> : <Text style={[typography.caption, { color: colors.textMuted }]}>{copy.purchase.accountInactive}</Text>}{!item.is_active && <Text style={[typography.caption, { color: colors.warning }]}>{copy.purchase.inactive}</Text>}<Feather name={rtl ? 'chevron-left' : 'chevron-right'} size={18} color={colors.textMuted} /></Pressable>} ListEmptyComponent={<EmptyState icon="truck" title={copy.purchase.noSuppliers} description={copy.purchase.noSuppliersDescription} actionLabel={copy.purchase.addSupplier} onAction={() => setSupplierEditor('new')} />} /> : historyMode === 'returns' ? <FlatList data={returns} keyExtractor={item => item.uuid} refreshing={loading} onRefresh={() => void refresh()} contentContainerStyle={[styles.list, { paddingBottom: bottomNavigationInset + spacing.md }, !returns.length && styles.empty]} ItemSeparatorComponent={() => <View style={styles.separator} />} renderItem={({ item }) => <Pressable accessibilityRole="button" accessibilityLabel={copy.purchase.viewReturn} onPress={() => void store.getPurchaseReturnDetail(item.id).then(value => { setReturnSucceeded(false); setReturnDetail(value); })} style={({ pressed }) => [styles.row, { backgroundColor: colors.surface }, pressed && styles.pressed]}><View style={styles.flex}><Text numberOfLines={1} style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.supplier_name_snapshot}</Text><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr', textAlign: rtl ? 'right' : 'left' }]}>{new Date(item.created_at).toLocaleString(store.language === 'ar' ? 'ar-SY' : 'en-US')} · {formatNumber(item.total_quantity, store.language)} {copy.common.itemsUnit}</Text></View><Text style={[typography.numericSmall, { color: colors.warning, writingDirection: 'ltr' }]}>{formatUsdCents(item.total_value_usd_cents, store.language)}</Text></Pressable>} ListEmptyComponent={<EmptyState icon="corner-up-left" title={copy.purchase.returnsTab} description={copy.purchase.noReturnable} />} /> : <FlatList data={receipts} keyExtractor={item => item.uuid} refreshing={loading} onRefresh={() => void refresh()} contentContainerStyle={[styles.list, { paddingBottom: bottomNavigationInset + spacing.md }, !receipts.length && styles.empty]} ItemSeparatorComponent={() => <View style={styles.separator} />} renderItem={({ item }) => <Pressable accessibilityRole="button" accessibilityLabel={copy.purchase.viewReceipt} onPress={() => void store.getPurchaseReceiptDetail(item.id).then(value => { setReceiptSucceeded(false); setReceiptDetail(value); })} style={({ pressed }) => [styles.row, { backgroundColor: colors.surface }, pressed && styles.pressed]}><View style={styles.flex}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><Text numberOfLines={1} style={[typography.bodyMedium, styles.flex, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.supplier_name_snapshot}</Text>{item.return_status !== 'none' && <Text style={[typography.caption, { color: colors.warning }]}>{item.return_status === 'full' ? copy.purchase.fullReturn : copy.purchase.partialReturn}</Text>}</View><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr', textAlign: rtl ? 'right' : 'left' }]}>{new Date(item.received_at).toLocaleString(store.language === 'ar' ? 'ar-SY' : 'en-US')} · {formatNumber(item.total_quantity, store.language)} {copy.common.itemsUnit}</Text></View><Text style={[typography.numericSmall, { color: colors.primary, writingDirection: 'ltr' }]}>{formatUsdCents(item.total_cost_usd_cents, store.language)}</Text></Pressable>} ListEmptyComponent={<EmptyState icon="inbox" title={copy.purchase.noReceipts} description={copy.purchase.noReceiptsDescription} actionLabel={copy.purchase.newReceipt} onAction={() => setReceiptEditor(true)} />} />}
    <SupplierEditor value={supplierEditor} language={store.language} onClose={() => setSupplierEditor(null)} onSaved={async () => { setSupplierEditor(null); await refresh(); }} />
    <SupplierDetail value={supplierDetail} language={store.language} onClose={() => setSupplierDetail(null)} onEdit={value => { setSupplierDetail(null); setSupplierEditor(value); }} onChanged={async () => { setSupplierDetail(null); await refresh(); }} />
    <ReceiptEditor visible={receiptEditor} language={store.language} onClose={() => setReceiptEditor(false)} onSaved={value => { setReceiptEditor(false); setReceiptSucceeded(true); setReceiptDetail(value); void refresh(); }} />
<ReceiptDetail value={receiptDetail} succeeded={receiptSucceeded} language={store.language} onView={() => setReceiptSucceeded(false)} onNew={() => { setReceiptDetail(null); setReceiptSucceeded(false); setReceiptEditor(true); }} onReturn={value => { setReceiptDetail(null); setReturnEditorReceipt(value); }} onOpenReturn={id => void store.getPurchaseReturnDetail(id).then(value => { setReceiptDetail(null); setReturnDetail(value); })} onClose={() => { setReceiptDetail(null); setReceiptSucceeded(false); }} />
    <PurchaseReturnEditor receipt={returnEditorReceipt} language={store.language} onClose={() => setReturnEditorReceipt(null)} onSaved={value => { setReturnEditorReceipt(null); setReturnSucceeded(true); setReturnDetail(value); void refresh(); }} />
    <PurchaseReturnDetail value={returnDetail} succeeded={returnSucceeded} language={store.language} onView={() => setReturnSucceeded(false)} onOriginal={id => void store.getPurchaseReceiptDetail(id).then(value => { setReturnDetail(null); setReceiptDetail(value); })} onClose={() => { setReturnDetail(null); setReturnSucceeded(false); }} />
  </View></ScreenContainer>;
}

function Chip({ label, active, onPress }: { label: string; active: boolean; onPress: () => void }) { const { colors } = useAppTheme(); return <Pressable accessibilityRole="button" accessibilityState={{ selected: active }} onPress={onPress} style={[styles.chip, { backgroundColor: active ? colors.primarySoft : colors.surface, borderColor: active ? colors.primary : colors.border }]}><Text style={[typography.caption, { color: active ? colors.primary : colors.textSecondary }]}>{label}</Text></Pressable>; }

function SupplierEditor({ value, language, onClose, onSaved }: { value: Supplier | 'new' | null; language: 'ar' | 'en'; onClose: () => void; onSaved: () => Promise<void> }) {
  const store = useAppStore(); const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); const guard = useRef(false); const [form, setForm] = useState<SupplierInput>({ name: '', phone: '', address: '', note: '' }); const [saving, setSaving] = useState(false);
  useEffect(() => setForm(value && value !== 'new' ? { name: value.name, phone: value.phone, address: value.address, note: value.note } : { name: '', phone: '', address: '', note: '' }), [value]); if (!value) return null;
  const submit = async () => { if (guard.current) return; if (!form.name.trim()) { snackbar.show({ text: copy.purchase.supplierRequired, tone: 'error' }); return; } guard.current = true; setSaving(true); try { if (value === 'new') await store.addSupplier(form); else await store.updateSupplier(value.id, form); await onSaved(); snackbar.show({ text: copy.purchase.supplierSaved, tone: 'success' }); } catch { snackbar.show({ text: copy.purchase.supplierFailed, tone: 'error' }); } finally { guard.current = false; setSaving(false); } };
  return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer keyboard><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.editor}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><Text style={[typography.titleLarge, styles.flex, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{value === 'new' ? copy.purchase.addSupplier : copy.purchase.editSupplier}</Text><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View><AppInput label={copy.purchase.supplierName} value={form.name} onChangeText={name => setForm(current => ({ ...current, name }))} maxLength={120} rtl={rtl} /><AppInput label={copy.purchase.phone} value={form.phone ?? ''} onChangeText={phone => setForm(current => ({ ...current, phone }))} keyboardType="phone-pad" maxLength={60} rtl={rtl} /><AppInput label={copy.purchase.address} value={form.address ?? ''} onChangeText={address => setForm(current => ({ ...current, address }))} maxLength={240} rtl={rtl} /><AppInput label={copy.purchase.supplierNote} value={form.note ?? ''} onChangeText={note => setForm(current => ({ ...current, note }))} maxLength={500} rtl={rtl} /><AppButton label={copy.common.save} icon="check" onPress={() => void submit()} disabled={!form.name.trim()} loading={saving} /></ScrollView></ScreenContainer></Modal>;
}

function SupplierDetail({ value, language, onClose, onEdit, onChanged }: { value: Supplier | null; language: 'ar' | 'en'; onClose: () => void; onEdit: (value: Supplier) => void; onChanged: () => Promise<void> }) {
  const store = useAppStore(); const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const [history, setHistory] = useState<PurchaseReceipt[]>([]); const [returnHistory, setReturnHistory] = useState<PurchaseReturn[]>([]);
  useEffect(() => { if (value) void Promise.all([store.queryPurchaseReceipts({ supplierId: value.id, sort: 'newest', limit: 10 }), store.queryPurchaseReturns({ supplierId: value.id, sort: 'newest', limit: 10 })]).then(([receipts, returns]) => { setHistory(receipts); setReturnHistory(returns); }); else { setHistory([]); setReturnHistory([]); } }, [store, value]);
  if (!value) return null;
  return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer keyboard><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.editor}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><Text style={[typography.titleLarge, styles.flex, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{value.name}</Text><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View>{[value.phone, value.address, value.note].filter(Boolean).map((text, index) => <Text key={index} style={[typography.body, { color: colors.textSecondary, textAlign: rtl ? 'right' : 'left', writingDirection: index === 0 ? 'ltr' : undefined }]}>{text}</Text>)}<SupplierAccountPanel supplier={value} language={language} onChanged={onChanged} /><Summary label={copy.purchase.receipts} value={formatNumber(value.receipt_count ?? 0, language)} /><Summary label={copy.purchase.supplierReturnsCount} value={formatNumber(value.return_count ?? 0, language)} /><Summary label={copy.purchase.latestReceipt} value={value.latest_receipt_at ? new Date(value.latest_receipt_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US') : '—'} /><Summary label={copy.purchase.latestReturn} value={value.latest_return_at ? new Date(value.latest_return_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US') : '—'} />{history.length > 0 && <><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.receiptHistory}</Text>{history.map(receipt => <View key={receipt.uuid} style={[styles.detailLine, { borderBottomColor: colors.border }]}><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(receipt.received_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')}</Text><Text style={[typography.numericSmall, { color: colors.textPrimary, writingDirection: 'ltr' }]}>{formatUsdCents(receipt.total_cost_usd_cents, language)}</Text></View>)}</>}{returnHistory.length > 0 && <><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.supplierReturns}</Text>{returnHistory.map(record => <View key={record.uuid} style={[styles.detailLine, { borderBottomColor: colors.border }]}><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(record.created_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')}</Text><Text style={[typography.numericSmall, { color: colors.warning, writingDirection: 'ltr' }]}>{formatUsdCents(record.total_value_usd_cents, language)}</Text></View>)}</>}<AppButton label={copy.purchase.editSupplier} variant="secondary" onPress={() => onEdit(value)} /><AppButton label={value.is_active ? copy.purchase.hideSupplier : copy.purchase.restoreSupplier} variant="secondary" onPress={() => void store.setSupplierActive(value.id, !value.is_active).then(onChanged)} /></ScrollView></ScreenContainer></Modal>;
}

function SupplierAccountPanel({ supplier, language, onChanged }: { supplier: Supplier; language: 'ar' | 'en'; onChanged: () => Promise<void> }) {
  const store = useAppStore(); const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); const guard = useRef(false);
  const [summary, setSummary] = useState<SupplierAccountSummary | null>(null); const [entries, setEntries] = useState<SupplierAccountEntry[]>([]); const [payments, setPayments] = useState<SupplierPayment[]>([]); const [selectedPayment, setSelectedPayment] = useState<SupplierPayment | null>(null);
  const [activationOpen, setActivationOpen] = useState(false); const [opening, setOpening] = useState('0.00'); const [activationConfirmationValue, setActivationConfirmationValue] = useState<number | null>(null); const [paymentOpen, setPaymentOpen] = useState(false); const [mode, setMode] = useState<PaymentMode>('SYP'); const [syp, setSyp] = useState(''); const [usd, setUsd] = useState(''); const [note, setNote] = useState(''); const [busy, setBusy] = useState(false); const [creditConfirmationAmount, setCreditConfirmationAmount] = useState<number | null>(null);
  const [entryType, setEntryType] = useState<SupplierAccountEntry['type'] | 'all'>('all'); const [statementPeriod, setStatementPeriod] = useState<'all' | 'month'>('all');
  const statementFrom = useMemo(() => { if (statementPeriod === 'all') return undefined; const now = new Date(); return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).toISOString(); }, [statementPeriod]);
  const reload = useCallback(async () => { const [account, statement, history] = await Promise.all([store.getSupplierAccountSummary(supplier.id), store.getSupplierAccountEntries(supplier.id, entryType, 200, statementFrom), store.getSupplierPayments(supplier.id)]); setSummary(account); setEntries(statement); setPayments(history); }, [entryType, statementFrom, store, supplier.id]);
  useEffect(() => { setSelectedPayment(null); void reload(); }, [reload]);
  const parsedSyp = /^\d+$/.test(syp.trim()) ? Number(syp) : 0; const parsedUsd = parseUsdToCents(usd) ?? 0;
  let preview: { totalUsdCents: number } | null = null; try { preview = calculateSupplierPaymentEquivalent({ supplierId: supplier.id, mode, sypAmount: parsedSyp, usdCents: parsedUsd }, store.exchangeRate); } catch { preview = null; }
  const nextBalance = summary && preview ? summary.balanceUsdCents - preview.totalUsdCents : summary?.balanceUsdCents ?? 0; const crossesCredit = !!summary && summary.balanceUsdCents >= 0 && nextBalance < 0; const creditConfirmed = !!preview && creditConfirmationAmount === preview.totalUsdCents;
  const setCreditConfirmed = (_value: boolean) => setCreditConfirmationAmount(null);
  const activate = async () => { const cents = parseSignedUsdToCents(opening); if (guard.current || cents == null) return; if (activationConfirmationValue !== cents) { setActivationConfirmationValue(cents); snackbar.show({ text: copy.purchase.confirmActivation, tone: 'info' }); return; } guard.current = true; setBusy(true); try { await store.activateSupplierAccount(supplier.id, cents); await reload(); setActivationOpen(false); setActivationConfirmationValue(null); snackbar.show({ text: copy.purchase.accountActivated, tone: 'success' }); await onChanged(); } catch { snackbar.show({ text: copy.purchase.accountActivationFailed, tone: 'error' }); } finally { guard.current = false; setBusy(false); } };
  const pay = async () => { if (guard.current || !preview || !store.activeCashSession) return; if (crossesCredit && !creditConfirmed) { setCreditConfirmationAmount(preview.totalUsdCents); snackbar.show({ text: copy.purchase.creditConfirmation, tone: 'info' }); return; } guard.current = true; setBusy(true); try { await store.createSupplierPayment({ supplierId: supplier.id, mode, sypAmount: parsedSyp, usdCents: parsedUsd, note }); await reload(); setPaymentOpen(false); setSyp(''); setUsd(''); setNote(''); setCreditConfirmationAmount(null); snackbar.show({ text: copy.purchase.paymentRecorded, tone: 'success' }); await onChanged(); } catch (error) { snackbar.show({ text: error instanceof Error && error.message === 'CASH_SESSION_REQUIRED' ? copy.purchase.activeSessionRequired : copy.purchase.paymentFailed, tone: 'error' }); } finally { guard.current = false; setBusy(false); } };
  if (!summary) return <View style={[styles.accountBlock, { backgroundColor: colors.surface }]}><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.accountInactive}</Text><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.accountInactiveHint}</Text>{activationOpen ? <><AppInput label={copy.purchase.openingBalanceUsd} value={opening} onChangeText={setOpening} keyboardType="numbers-and-punctuation" rtl={rtl} /><AppButton label={copy.purchase.activateAccount} icon="check" onPress={() => void activate()} disabled={parseSignedUsdToCents(opening) == null} loading={busy} /></> : <AppButton label={copy.purchase.activateAccount} onPress={() => setActivationOpen(true)} />}</View>;
  const balanceLabel = summary.balanceUsdCents > 0 ? copy.purchase.payable : summary.balanceUsdCents < 0 ? copy.purchase.supplierCredit : copy.purchase.settled;
  const historyControls = <><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}><Chip label={copy.purchase.all} active={statementPeriod === 'all'} onPress={() => setStatementPeriod('all')} /><Chip label={copy.purchase.month} active={statementPeriod === 'month'} onPress={() => setStatementPeriod('month')} /></ScrollView><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['all','opening','purchase','purchase_return','payment'] as const).map(value => <Chip key={value} label={value === 'all' ? copy.purchase.all : ({ opening: copy.purchase.accountOpening, purchase: copy.purchase.accountPurchase, purchase_return: copy.purchase.accountReturn, payment: copy.purchase.accountPayment })[value]} active={entryType === value} onPress={() => setEntryType(value)} />)}</ScrollView></>;
  const paymentHistory = payments.length ? <><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.paymentHistory}</Text>{payments.map(payment => <Pressable key={payment.uuid} accessibilityRole="button" accessibilityLabel={copy.purchase.viewPayment} onPress={() => void store.getSupplierPaymentDetail(payment.id).then(setSelectedPayment)} style={[styles.detailLine, { borderBottomColor: colors.border }]}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><Text style={[typography.bodyMedium, styles.flex, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{payment.payment_mode}</Text><Text style={[typography.numericSmall, { color: colors.success, writingDirection: 'ltr' }]}>{formatUsdCents(payment.total_usd_equivalent_cents, language)}</Text></View><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(payment.occurred_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')} · {payment.uuid.slice(0, 8)}</Text></Pressable>)}{selectedPayment && <View style={[styles.line, { backgroundColor: colors.background }]}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><Text style={[typography.title, styles.flex, { color: colors.textPrimary }]}>{copy.purchase.viewPayment}</Text><AppButton label={copy.common.close} variant="ghost" onPress={() => setSelectedPayment(null)} /></View><Summary label={copy.purchase.supplier} value={selectedPayment.supplier_name_snapshot} /><Summary label={copy.purchase.paymentMode} value={selectedPayment.payment_mode} />{selectedPayment.tenders?.map(tender => <Summary key={tender.uuid} label={tender.currency === 'SYP' ? copy.purchase.sypAmount : copy.purchase.usdAmount} value={tender.currency === 'SYP' ? `${formatNumber(tender.amount_minor, language)} SYP` : formatUsdCents(tender.amount_minor, language)} />)}{selectedPayment.exchange_rate_syp_per_usd && <Summary label={copy.purchase.exchangeSnapshot} value={`${formatNumber(selectedPayment.exchange_rate_syp_per_usd, language)} SYP/USD`} />}<Summary label={copy.purchase.usdEquivalent} value={formatUsdCents(selectedPayment.total_usd_equivalent_cents, language)} /><Summary label={copy.purchase.newBalance} value={formatUsdCents(selectedPayment.balance_after_usd_cents, language)} /><Summary label={copy.purchase.cashSessionReference} value={String(selectedPayment.cash_session_id)} />{selectedPayment.note && <Text style={[typography.body, { color: colors.textSecondary, textAlign: rtl ? 'right' : 'left' }]}>{selectedPayment.note}</Text>}<AppButton label={copy.purchase.sharePayment} icon="share-2" variant="secondary" onPress={() => void shareSupplierPayment(selectedPayment, language)} /></View>}</> : null;
  return <View style={[styles.accountBlock, { backgroundColor: colors.surface }]}>
    <View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}>
      <Text style={[typography.title, styles.flex, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.accountStatement}</Text>
      <Text style={[typography.numericSmall, { color: summary.balanceUsdCents > 0 ? colors.warning : colors.success, writingDirection: 'ltr' }]}>{balanceLabel}: {formatUsdCents(Math.abs(summary.balanceUsdCents), language)}</Text>
    </View>
    <Summary label={copy.purchase.totalPurchases} value={formatUsdCents(summary.purchasesUsdCents, language)} />
    <Summary label={copy.purchase.returnedGoodsValue} value={formatUsdCents(summary.returnsUsdCents, language)} />
    <Summary label={copy.purchase.totalPayments} value={formatUsdCents(summary.paymentsUsdCents, language)} />
    {paymentOpen ? <View style={styles.paymentForm}>
      <Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.paySupplier}</Text>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{(['SYP','USD','MIXED'] as PaymentMode[]).map(value => <Chip key={value} label={value} active={mode === value} onPress={() => { setMode(value); setCreditConfirmed(false); }} />)}</ScrollView>
      {mode !== 'USD' && <AppInput label={copy.purchase.sypAmount} value={syp} onChangeText={setSyp} keyboardType="number-pad" rtl={rtl} />}
      {mode !== 'SYP' && <AppInput label={copy.purchase.usdAmount} value={usd} onChangeText={setUsd} keyboardType="decimal-pad" rtl={rtl} />}
      <AppInput label={copy.purchase.supplierNote} value={note} onChangeText={setNote} maxLength={500} rtl={rtl} />
      <Summary label={copy.purchase.exchangeSnapshot} value={`${formatNumber(store.exchangeRate, language)} SYP/USD`} />
      <Summary label={copy.purchase.usdEquivalent} value={formatUsdCents(preview?.totalUsdCents ?? 0, language)} />
      <Summary label={copy.purchase.newBalance} value={formatUsdCents(nextBalance, language)} />
      {!store.activeCashSession && <Text style={[typography.caption, { color: colors.warning, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.activeSessionRequired}</Text>}
      {crossesCredit && !creditConfirmed && <Text style={[typography.caption, { color: colors.warning, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.creditConfirmation}</Text>}
      <AppButton label={copy.purchase.confirmPayment} icon="check" onPress={() => void pay()} disabled={!preview || !store.activeCashSession} loading={busy} />
      <AppButton label={copy.common.cancel} variant="ghost" onPress={() => setPaymentOpen(false)} />
    </View> : <AppButton label={copy.purchase.paySupplier} onPress={() => setPaymentOpen(true)} />}
    <View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}>
      <Text style={[typography.title, styles.flex, { color: colors.textPrimary }]}>{copy.purchase.accountEntries}</Text>
      <AppButton label={copy.purchase.shareStatement} variant="ghost" onPress={() => void shareSupplierStatement(summary.supplier, entries, language)} />
    </View>
    {historyControls}
    {entries.length ? entries.map(entry => <View key={entry.uuid} style={[styles.detailLine, { borderBottomColor: colors.border }]}>
      <View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}>
        <Text style={[typography.bodyMedium, styles.flex, { color: colors.textPrimary }]}>{({ opening: copy.purchase.accountOpening, purchase: copy.purchase.accountPurchase, purchase_return: copy.purchase.accountReturn, payment: copy.purchase.accountPayment })[entry.type]}</Text>
        <Text style={[typography.numericSmall, { color: entry.delta_usd_cents >= 0 ? colors.warning : colors.success, writingDirection: 'ltr' }]}>{formatUsdCents(entry.delta_usd_cents, language)}</Text>
      </View>
      <Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(entry.occurred_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')} · {formatUsdCents(entry.running_balance_usd_cents ?? 0, language)}</Text>
    </View>) : <Text style={[typography.caption, { color: colors.textMuted }]}>{copy.purchase.noAccountEntries}</Text>}
    {paymentHistory}
    <Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.accountImmutable}</Text>
  </View>;
}

function ReceiptEditor({ visible, language, onClose, onSaved }: { visible: boolean; language: 'ar' | 'en'; onClose: () => void; onSaved: (value: PurchaseReceipt) => void }) {
  const store = useAppStore(); const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); const guard = useRef(false); const [suppliers, setSuppliers] = useState<Supplier[]>([]); const [supplierId, setSupplierId] = useState<number | null>(null); const [reference, setReference] = useState(''); const [note, setNote] = useState(''); const [search, setSearch] = useState(''); const [lines, setLines] = useState<ReceiptLine[]>([]); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!visible) return; void store.getSuppliers('', 'name', false).then(setSuppliers); setSupplierId(null); setReference(''); setNote(''); setSearch(''); setLines([]); }, [store, visible]);
  const products = useMemo(() => { const term = search.trim().toLocaleLowerCase(); return store.products.filter(product => product.is_active !== 0 && !lines.some(line => line.product.id === product.id) && (!term || product.name.toLocaleLowerCase().includes(term) || product.barcode === search.trim())); }, [lines, search, store.products]);
  const total = lines.reduce((sum, line) => { const quantity = Number(line.quantity); const cost = parseUsdToCents(line.cost); return sum + (Number.isSafeInteger(quantity) && quantity > 0 && cost != null ? quantity * cost : 0); }, 0);
  const submit = async () => { if (guard.current) return; if (!supplierId) { snackbar.show({ text: copy.purchase.supplierRequired, tone: 'error' }); return; } if (!lines.length) { snackbar.show({ text: copy.purchase.emptyItems, tone: 'error' }); return; } const items: PurchaseReceiptInputItem[] = []; for (const line of lines) { const quantity = Number(line.quantity); const cost = parseUsdToCents(line.cost); if (!Number.isSafeInteger(quantity) || quantity <= 0 || cost == null) { snackbar.show({ text: copy.purchase.invalidItem, tone: 'error' }); return; } items.push({ productId: line.product.id, quantity, unitCostUsdCents: cost }); } guard.current = true; setSaving(true); try { onSaved(await store.createPurchaseReceipt({ supplierId, referenceNumber: reference, note, items })); snackbar.show({ text: copy.purchase.received, tone: 'success' }); } catch { snackbar.show({ text: copy.purchase.receiptFailed, tone: 'error' }); } finally { guard.current = false; setSaving(false); } };
  if (!visible) return null; return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer keyboard><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.editor}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={styles.flex}><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.receiveGoods}</Text><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.stockOnlyNote}</Text></View><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.supplierPicker}</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{suppliers.map(item => <Chip key={item.uuid} label={item.name} active={supplierId === item.id} onPress={() => setSupplierId(item.id)} />)}</ScrollView><AppInput label={copy.purchase.referenceNumber} value={reference} onChangeText={setReference} maxLength={120} rtl={rtl} /><AppInput label={copy.purchase.supplierNote} value={note} onChangeText={setNote} maxLength={500} rtl={rtl} /><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.items}</Text><SearchInput value={search} onChangeText={setSearch} placeholder={copy.purchase.productSearch} clearLabel={copy.common.clearSearch} rtl={rtl} />{search.trim() && products.slice(0, 12).map(product => <Pressable key={product.id} accessibilityRole="button" accessibilityState={{ disabled: !product.inventory_tracking_enabled }} onPress={() => { if (!product.inventory_tracking_enabled) { snackbar.show({ text: copy.purchase.trackingDisabled, tone: 'info' }); return; } setLines(current => [...current, { product, quantity: '1', cost: product.cost_currency === 'USD' ? product.cost_usd.toFixed(2) : '' }]); setSearch(''); }} style={[styles.productChoice, { borderColor: colors.border }]}><Text style={[typography.bodyMedium, { color: colors.textPrimary }]}>{product.name}</Text><Text style={[typography.caption, { color: product.inventory_tracking_enabled ? colors.textMuted : colors.warning, writingDirection: 'ltr' }]}>{product.inventory_tracking_enabled ? `${copy.purchase.currentCost}: ${product.cost_currency === 'USD' ? formatProductUsd(product.cost_usd, language) : `${formatNumber(product.cost_syp ?? 0, language)} ${copy.common.syp}`}` : copy.purchase.trackingDisabled}</Text></Pressable>)}{lines.map((line, index) => <View key={line.product.uuid} style={[styles.line, { backgroundColor: colors.surface }]}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={styles.flex}><Text style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{line.product.name}</Text><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{copy.purchase.currentCost}: {line.product.cost_currency === 'USD' ? formatProductUsd(line.product.cost_usd, language) : `${formatNumber(line.product.cost_syp ?? 0, language)} ${copy.common.syp}`}</Text></View><Pressable accessibilityRole="button" accessibilityLabel={copy.purchase.removeLine} hitSlop={8} onPress={() => setLines(current => current.filter((_, lineIndex) => lineIndex !== index))} style={styles.iconButton}><Feather name="x" size={20} color={colors.warning} /></Pressable></View><AppInput label={copy.purchase.unitCost} value={line.cost} onChangeText={cost => setLines(current => current.map((item, lineIndex) => lineIndex === index ? { ...item, cost } : item))} keyboardType="decimal-pad" rtl={rtl} /><AppInput label={copy.purchase.receivedQuantity} value={line.quantity} onChangeText={quantity => setLines(current => current.map((item, lineIndex) => lineIndex === index ? { ...item, quantity } : item))} keyboardType="number-pad" rtl={rtl} /></View>)}<Summary label={copy.purchase.totalQuantity} value={formatNumber(lines.reduce((sum, line) => sum + (Number(line.quantity) || 0), 0), language)} /><Summary label={copy.purchase.totalValue} value={formatUsdCents(total, language)} /><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.immutable}</Text><AppButton label={copy.purchase.receiveGoods} icon="check" onPress={() => void submit()} disabled={!supplierId || !lines.length} loading={saving} /></ScrollView></ScreenContainer></Modal>;
}

function ReceiptDetail({ value, succeeded, language, onView, onNew, onReturn, onOpenReturn, onClose }: { value: PurchaseReceipt | null; succeeded: boolean; language: 'ar' | 'en'; onView: () => void; onNew: () => void; onReturn: (value: PurchaseReceipt) => void; onOpenReturn: (id: number) => void; onClose: () => void }) {
  const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); if (!value) return null;
  const share = () => void sharePurchaseReceipt(value, language).then(() => snackbar.show({ text: copy.purchase.reportReady, tone: 'success' })).catch(() => snackbar.show({ text: copy.purchase.reportFailed, tone: 'error' }));
  const canReturn = value.items?.some(item => (item.max_return_now ?? 0) > 0) ?? false;
  return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer><ScrollView contentContainerStyle={styles.editor}>{succeeded ? <><View style={styles.successIcon}><Feather name="check" size={32} color={colors.success} /></View><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: 'center' }]}>{copy.purchase.received}</Text><Text style={[typography.bodyMedium, { color: colors.textSecondary, textAlign: 'center' }]}>{value.supplier_name_snapshot}</Text><Summary label={copy.purchase.items} value={formatNumber(value.item_count, language)} /><Summary label={copy.purchase.totalQuantity} value={formatNumber(value.total_quantity, language)} /><Summary label={copy.purchase.totalValue} value={formatUsdCents(value.total_cost_usd_cents, language)} /><AppButton label={copy.purchase.viewReceipt} icon="file-text" onPress={onView} /><AppButton label={copy.purchase.shareReceipt} icon="share-2" variant="secondary" onPress={share} /><AppButton label={copy.purchase.anotherReceipt} icon="plus" variant="secondary" onPress={onNew} /><AppButton label={copy.common.done} variant="ghost" onPress={onClose} /></> : <><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={styles.flex}><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.receiptId} <Text style={{ writingDirection: 'ltr' }}>{value.uuid.slice(0, 8)}</Text></Text><Text style={[typography.bodyMedium, { color: colors.textSecondary, textAlign: rtl ? 'right' : 'left' }]}>{value.supplier_name_snapshot}</Text></View><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(value.received_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')}</Text>{value.reference_number && <Summary label={copy.purchase.referenceNumber} value={value.reference_number} />}{value.note && <Text style={[typography.body, { color: colors.textSecondary, textAlign: rtl ? 'right' : 'left' }]}>{value.note}</Text>}{value.items?.map(item => <View key={item.uuid} style={[styles.detailLine, { borderBottomColor: colors.border }]}><Text style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.product_name_snapshot}</Text><Text style={[typography.caption, { color: colors.textSecondary, writingDirection: 'ltr' }]}>{formatNumber(item.quantity, language)} × {formatUsdCents(item.unit_cost_usd_cents, language)} = {formatUsdCents(item.line_total_usd_cents, language)}</Text>{(item.returned_quantity ?? 0) > 0 && <Text style={[typography.caption, { color: colors.warning, writingDirection: 'ltr' }]}>{copy.purchase.returnedPreviously}: {formatNumber(item.returned_quantity ?? 0, language)} · {copy.purchase.remainingReturnable}: {formatNumber(item.remaining_returnable_quantity ?? 0, language)}</Text>}</View>)}<Summary label={copy.purchase.originalValue} value={formatUsdCents(value.total_cost_usd_cents, language)} /><Summary label={copy.purchase.returnedGoodsValue} value={formatUsdCents(value.returned_value_usd_cents ?? 0, language)} /><Summary label={copy.purchase.remainingHistoricalValue} value={formatUsdCents(value.total_cost_usd_cents - (value.returned_value_usd_cents ?? 0), language)} />{value.returns && value.returns.length > 0 && <><Text style={[typography.title, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.supplierReturns}</Text>{value.returns.map(record => <Pressable key={record.uuid} accessibilityRole="button" accessibilityLabel={copy.purchase.viewReturn} onPress={() => onOpenReturn(record.id)} style={[styles.detailLine, { borderBottomColor: colors.border }]}><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(record.created_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')}</Text><Text style={[typography.numericSmall, { color: colors.warning, writingDirection: 'ltr' }]}>{formatNumber(record.total_quantity, language)} · {formatUsdCents(record.total_value_usd_cents, language)}</Text></Pressable>)}</>}<Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.immutable}</Text>{canReturn && <AppButton label={copy.purchase.returnToSupplier} icon="corner-up-left" onPress={() => onReturn(value)} />}<AppButton label={copy.purchase.shareReceipt} icon="share-2" variant="secondary" onPress={share} /></>}</ScrollView></ScreenContainer></Modal>;
}

function PurchaseReturnEditor({ receipt, language, onClose, onSaved }: { receipt: PurchaseReceipt | null; language: 'ar' | 'en'; onClose: () => void; onSaved: (value: PurchaseReturn) => void }) {
  const store = useAppStore(); const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); const guard = useRef(false); const [quantities, setQuantities] = useState<Record<number, string>>({}); const [reference, setReference] = useState(''); const [note, setNote] = useState(''); const [saving, setSaving] = useState(false);
  useEffect(() => { setQuantities(Object.fromEntries((receipt?.items ?? []).map(item => [item.id, '0']))); setReference(''); setNote(''); }, [receipt]);
  if (!receipt) return null;
  const selections: PurchaseReturnInputItem[] = []; let totalQuantity = 0; let totalValue = 0; let invalid = false;
  for (const item of receipt.items ?? []) { const quantity = Number(quantities[item.id] ?? 0); if (!Number.isSafeInteger(quantity) || quantity < 0 || quantity > (item.max_return_now ?? 0)) invalid = true; if (quantity > 0) { selections.push({ purchaseReceiptItemId: item.id, quantity }); totalQuantity += quantity; totalValue += quantity * item.unit_cost_usd_cents; } }
const submit = async () => { if (guard.current || invalid || !selections.length) return; guard.current = true; setSaving(true); try { onSaved(await store.createPurchaseReturn({ purchaseReceiptId: receipt.id, referenceNumber: reference, note, items: selections })); snackbar.show({ text: copy.purchase.returnSucceeded, tone: 'success' }); } catch (error) { const message = error instanceof Error && error.message === 'INSUFFICIENT_STOCK' ? copy.purchase.insufficientStock : error instanceof Error && error.message === 'PURCHASE_OVER_RETURN' ? copy.purchase.noReturnable : error instanceof Error && error.message === 'PURCHASE_RETURN_PRODUCT_UNAVAILABLE' ? copy.purchase.productUnavailable : copy.purchase.returnFailed; snackbar.show({ text: message, tone: 'error' }); } finally { guard.current = false; setSaving(false); } };
  return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer keyboard><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.editor}><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={styles.flex}><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.returnToSupplier}</Text><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.originalReceipt} <Text style={{ writingDirection: 'ltr' }}>{receipt.uuid.slice(0, 8)}</Text></Text></View><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View><AppInput label={copy.purchase.referenceNumber} value={reference} onChangeText={setReference} maxLength={120} rtl={rtl} /><AppInput label={copy.purchase.supplierNote} value={note} onChangeText={setNote} maxLength={500} rtl={rtl} />{receipt.items?.map(item => <View key={item.uuid} style={[styles.line, { backgroundColor: colors.surface }]}><Text style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.product_name_snapshot}</Text><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{copy.purchase.receivedQuantity}: {formatNumber(item.quantity, language)} · {copy.purchase.returnedPreviously}: {formatNumber(item.returned_quantity ?? 0, language)}</Text><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{copy.purchase.availableStock}: {formatNumber(item.inventory_quantity ?? 0, language)} · {copy.purchase.maximumReturn}: {formatNumber(item.max_return_now ?? 0, language)}</Text><AppInput label={copy.purchase.returnQuantity} accessibilityLabel={`${copy.purchase.returnQuantity} ${item.product_name_snapshot}`} value={quantities[item.id] ?? '0'} onChangeText={quantity => setQuantities(current => ({ ...current, [item.id]: quantity.replace(/[^0-9]/g, '') }))} keyboardType="number-pad" rtl={rtl} /></View>)}<Summary label={copy.purchase.returnedQuantity} value={formatNumber(totalQuantity, language)} /><Summary label={copy.purchase.returnedGoodsValue} value={formatUsdCents(totalValue, language)} /><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.informationalValue}</Text><AppButton label={copy.purchase.confirmReturn} icon="check" onPress={() => void submit()} disabled={invalid || !selections.length} loading={saving} /></ScrollView></ScreenContainer></Modal>;
}

function PurchaseReturnDetail({ value, succeeded, language, onView, onOriginal, onClose }: { value: PurchaseReturn | null; succeeded: boolean; language: 'ar' | 'en'; onView: () => void; onOriginal: (id: number) => void; onClose: () => void }) {
  const copy = uiText(language); const rtl = language === 'ar'; const { colors } = useAppTheme(); const snackbar = useSnackbar(); if (!value) return null;
  const share = () => void sharePurchaseReturn(value, language).then(() => snackbar.show({ text: copy.purchase.returnReportReady, tone: 'success' })).catch(() => snackbar.show({ text: copy.purchase.returnReportFailed, tone: 'error' }));
  return <Modal visible animationType="slide" onRequestClose={onClose}><ScreenContainer><ScrollView contentContainerStyle={styles.editor}>{succeeded ? <><View style={styles.successIcon}><Feather name="check" size={32} color={colors.success} /></View><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: 'center' }]}>{copy.purchase.returnSucceeded}</Text><Text style={[typography.bodyMedium, { color: colors.textSecondary, textAlign: 'center' }]}>{value.supplier_name_snapshot}</Text><Summary label={copy.purchase.totalQuantity} value={formatNumber(value.total_quantity, language)} /><Summary label={copy.purchase.historicalValue} value={formatUsdCents(value.total_value_usd_cents, language)} /><AppButton label={copy.purchase.viewReturn} icon="file-text" onPress={onView} /><AppButton label={copy.purchase.shareReturn} icon="share-2" variant="secondary" onPress={share} /><AppButton label={copy.purchase.originalReceipt} variant="secondary" onPress={() => onOriginal(value.purchase_receipt_id)} /><AppButton label={copy.common.done} variant="ghost" onPress={onClose} /></> : <><View style={[styles.titleRow, { flexDirection: rtl ? 'row-reverse' : 'row' }]}><View style={styles.flex}><Text style={[typography.titleLarge, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.returnDocument}</Text><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{copy.purchase.returnId}: {value.uuid.slice(0, 8)}</Text></View><AppButton label={copy.common.close} variant="ghost" onPress={onClose} /></View><Summary label={copy.purchase.supplier} value={value.supplier_name_snapshot} /><Summary label={copy.purchase.originalReceipt} value={(value.purchase_receipt_uuid ?? '').slice(0, 8)} /><Text style={[typography.caption, { color: colors.textMuted, writingDirection: 'ltr' }]}>{new Date(value.created_at).toLocaleString(language === 'ar' ? 'ar-SY' : 'en-US')}</Text>{value.reference_number && <Summary label={copy.purchase.referenceNumber} value={value.reference_number} />}{value.note && <Text style={[typography.body, { color: colors.textSecondary, textAlign: rtl ? 'right' : 'left' }]}>{value.note}</Text>}{value.items?.map(item => <View key={item.uuid} style={[styles.detailLine, { borderBottomColor: colors.border }]}><Text style={[typography.bodyMedium, { color: colors.textPrimary, textAlign: rtl ? 'right' : 'left' }]}>{item.product_name_snapshot}</Text><Text style={[typography.caption, { color: colors.textSecondary, writingDirection: 'ltr' }]}>{formatNumber(item.quantity, language)} × {formatUsdCents(item.unit_cost_usd_cents, language)} = {formatUsdCents(item.line_total_usd_cents, language)}</Text></View>)}<Summary label={copy.purchase.totalQuantity} value={formatNumber(value.total_quantity, language)} /><Summary label={copy.purchase.historicalValue} value={formatUsdCents(value.total_value_usd_cents, language)} /><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.returnImmutable}</Text><Text style={[typography.caption, { color: colors.textMuted, textAlign: rtl ? 'right' : 'left' }]}>{copy.purchase.informationalValue}</Text><AppButton label={copy.purchase.originalReceipt} variant="secondary" onPress={() => onOriginal(value.purchase_receipt_id)} /><AppButton label={copy.purchase.shareReturn} icon="share-2" variant="secondary" onPress={share} /></>}</ScrollView></ScreenContainer></Modal>;
}

function Summary({ label, value }: { label: string; value: string }) { const { colors } = useAppTheme(); return <View style={[styles.summary, { borderBottomColor: colors.border }]}><Text style={[typography.body, { color: colors.textSecondary }]}>{label}</Text><Text style={[typography.numericSmall, { color: colors.textPrimary, writingDirection: 'ltr' }]}>{value}</Text></View>; }

